@sandbox_command_event_group.command(name=cli_util.override('generative_ai_sandbox.stream_sandbox_command_events.command_name', 'stream'), help=u"""Streams command events for an existing sandbox command from `fromSeq` through `untilSeq` using Server-Sent Events. Each SSE `data` field contains a serialized SandboxCommandEvent. \n[Command Reference](streamSandboxCommandEvents)""")
@cli_util.option('--sandbox-id', required=True, help=u"""Sandbox identifier. Newly generated Sandbox IDs use `sbx-` followed by 16 lowercase base32 characters (`a-z2-7`); existing legacy IDs remain accepted.""")
@cli_util.option('--command-id', required=True, help=u"""Sandbox command identifier.""")
@cli_util.option('--file', type=click.File(mode='wb'), required=True, help="The name of the file that will receive the response data, or '-' to write to STDOUT.")
@cli_util.option('--from-seq', type=click.INT, help=u"""The first command event sequence number to include.""")
@cli_util.option('--until-seq', type=click.INT, help=u"""The last command event sequence number to include. If omitted, all available events from `fromSeq` are included.""")
@json_skeleton_utils.get_cli_json_input_option({})
@cli_util.help_option
@click.pass_context
@json_skeleton_utils.json_skeleton_generation_handler(input_params_to_complex_types={})
@cli_util.wrap_exceptions
def stream_sandbox_command_events(ctx, from_json, file, sandbox_id, command_id, from_seq, until_seq):

    if isinstance(sandbox_id, six.string_types) and len(sandbox_id.strip()) == 0:
        raise click.UsageError('Parameter --sandbox-id cannot be whitespace or empty string')

    if isinstance(command_id, six.string_types) and len(command_id.strip()) == 0:
        raise click.UsageError('Parameter --command-id cannot be whitespace or empty string')

    kwargs = {}
    if from_seq is not None:
        kwargs['from_seq'] = from_seq
    if until_seq is not None:
        kwargs['until_seq'] = until_seq
    kwargs['opc_request_id'] = cli_util.use_or_generate_request_id(ctx.obj['request_id'])
    client = cli_util.build_client('generative_ai_sandbox', 'generative_ai_sandbox', ctx)
    result = client.stream_sandbox_command_events(
        sandbox_id=sandbox_id,
        command_id=command_id,
        **kwargs
    )

    # If outputting to stdout we don't want to print a progress bar because it will get mixed up with the output
    # Also we need a non-zero Content-Length in order to display a meaningful progress bar
    bar = None
    if hasattr(file, 'name') and file.name != '<stdout>' and 'Content-Length' in result.headers:
        content_length = int(result.headers['Content-Length'])
        if content_length > 0:
            bar = click.progressbar(length=content_length, label='Downloading file')

    try:
        if bar:
            bar.__enter__()

        # TODO: Make the download size a configurable option
        # use decode_content=True to automatically unzip service responses (this should be overridden for object storage)
        for chunk in result.data.raw.stream(cli_constants.MEBIBYTE, decode_content=True):
            if bar:
                bar.update(len(chunk))
            file.write(chunk)
    finally:
        if bar:
            bar.render_finish()
        file.close()


